package adapters

import (
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type HerdrScanner struct{}

func (s HerdrScanner) Name() string {
	return "herdr"
}

func (s HerdrScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if _, err := exec.LookPath("herdr"); err != nil {
		result.Skipped = true
		result.Message = "herdr not found"
		return result
	}
	out, err := exec.CommandContext(ctx, "herdr", herdrAgentListArgs()...).Output()
	if err != nil {
		if ctx.Err() != nil {
			result.Err = ctx.Err()
			return result
		}
		result.Skipped = true
		result.Message = "herdr agent list unavailable; is the server running?"
		return result
	}
	var payload any
	if err := json.Unmarshal(out, &payload); err != nil {
		result.Err = err
		return result
	}
	items, recognized := herdrAgentItems(payload)
	if !recognized {
		result.Err = fmt.Errorf("unrecognized herdr agent list response")
		return result
	}
	now := time.Now().UTC()
	for index, item := range items {
		target, paneID := herdrTarget(item)
		if target == "" {
			result.Sessions = nil
			result.Runtimes = nil
			result.Err = fmt.Errorf("herdr agent list item %d has no agent or pane identity", index)
			return result
		}
		cwd := firstString(item, "foreground_cwd", "cwd", "project_path", "workspace_cwd")
		agent := firstNonEmpty(firstString(item, "agent", "kind", "agent_kind", "label", "display_agent"), "agent")
		status := normalizeStatus(firstString(item, "agent_status", "status", "state", "agent_state", "lifecycle_state"))
		if status == "" {
			status = core.StatusUnknown
		}
		title := firstString(item, "title", "display_title", "name", "label")
		if title == "" {
			title = "Herdr: " + core.Truncate(target, 32)
		}
		session := core.NewSession("herdr", target)
		session.ProjectPath = cwd
		session.Agent = agent
		session.Title = title
		session.Status = status
		session.LastActivityAt = now
		session.CreatedAt = now
		session.AttachCommand = "herdr agent attach " + core.ShellQuote(target)
		if ref, sessionAgent := agentSessionRef(item); ref != "" {
			session.ResumeCommand = resumeCommand(firstNonEmpty(sessionAgent, agent), ref)
			session.RawPath = ref
		}
		result.Sessions = append(result.Sessions, session)
		result.Runtimes = append(result.Runtimes, core.RuntimeInstance{
			ID:            core.RuntimeID("herdr", target),
			SessionID:     session.ID,
			Backend:       "herdr",
			NativeID:      target,
			Surface:       firstNonEmpty(paneID, target),
			ProjectPath:   cwd,
			Command:       agent,
			Status:        status,
			AttachCommand: session.AttachCommand,
			UpdatedAt:     now,
		})
	}
	result.SnapshotComplete = true
	return result
}

func herdrAgentListArgs() []string {
	return []string{"agent", "list"}
}

func herdrAgentItems(v any) ([]map[string]any, bool) {
	switch x := v.(type) {
	case []any:
		return strictMapsFromArray(x)
	case map[string]any:
		for _, key := range []string{"result", "response"} {
			if nested, ok := x[key]; ok {
				return herdrAgentItems(nested)
			}
		}
		for _, key := range []string{"agents", "items", "data", "results"} {
			if nested, ok := x[key]; ok {
				return herdrAgentItems(nested)
			}
		}
		if isHerdrAgentRecord(x) {
			return []map[string]any{x}, true
		}
		return nil, false
	default:
		return nil, false
	}
}

func isHerdrAgentRecord(item map[string]any) bool {
	if firstString(item, "pane_id", "paneId", "public_pane_id", "name", "agent_name", "agent_id") != "" {
		return true
	}
	if firstString(item, "id") == "" {
		return false
	}
	for _, key := range []string{
		"agent_status",
		"agent_state",
		"lifecycle_state",
		"foreground_cwd",
		"agent_session",
	} {
		if _, ok := item[key]; ok {
			return true
		}
	}
	return false
}

func strictMapsFromArray(arr []any) ([]map[string]any, bool) {
	out := make([]map[string]any, 0, len(arr))
	for _, item := range arr {
		m, ok := item.(map[string]any)
		if !ok {
			return nil, false
		}
		out = append(out, m)
	}
	return out, true
}

func firstString(m map[string]any, keys ...string) string {
	for _, key := range keys {
		if v, ok := m[key]; ok {
			if s := stringFromAny(v); s != "" {
				return s
			}
		}
	}
	return ""
}

func stringFromAny(v any) string {
	switch t := v.(type) {
	case string:
		return strings.TrimSpace(t)
	case map[string]any:
		return firstString(t, "pane_id", "id", "name", "label", "path", "agent_status", "state", "status", "cwd")
	default:
		return ""
	}
}

func herdrTarget(item map[string]any) (target, paneID string) {
	paneID = firstString(item, "pane_id", "paneId", "public_pane_id")
	target = firstString(item, "name", "agent_name", "agent_id")
	if target == "" {
		target = firstString(item, "id")
	}
	if target == "" {
		target = paneID
	}
	if paneID == "" {
		paneID = firstString(item, "terminal_id", "terminalId")
	}
	return target, paneID
}

func agentSessionRef(item map[string]any) (ref, agent string) {
	if ref := firstString(item, "agent_session_id", "session_id", "agent_session_path", "session_path"); ref != "" {
		return ref, ""
	}
	if nested, ok := item["agent_session"].(map[string]any); ok {
		return firstString(nested, "value", "id", "session_id", "path", "agent_session_path"),
			firstString(nested, "agent")
	}
	return "", ""
}

func resumeCommand(agent, ref string) string {
	switch strings.ToLower(agent) {
	case "claude", "claude code", "claude-code":
		return "claude --resume " + core.ShellQuote(ref)
	case "copilot", "github copilot cli":
		return "copilot --resume=" + core.ShellQuote(ref)
	case "hermes", "hermes agent":
		return "hermes --resume " + core.ShellQuote(ref)
	case "opencode":
		return "opencode --session " + core.ShellQuote(ref)
	case "codex":
		return "codex resume " + core.ShellQuote(ref)
	default:
		return ""
	}
}

func normalizeStatus(status string) string {
	switch strings.ToLower(strings.TrimSpace(status)) {
	case "blocked", "waiting", "needs_attention", "needs-attention":
		return core.StatusNeedsAttention
	case "working", "busy", "running":
		return core.StatusWorking
	case "idle", "ready":
		return core.StatusIdle
	case "done", "complete", "completed":
		return core.StatusDone
	case "stale":
		return core.StatusStale
	default:
		return ""
	}
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

package adapters

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

func TestObjectListReadsNestedResultAgents(t *testing.T) {
	var payload any
	data := []byte(`{
		"result": {
			"agents": [
				{
					"name": "auth-agent",
					"pane_id": "w1:p1",
					"kind": "claude",
					"agent_status": "blocked",
					"foreground_cwd": "/repo",
					"agent_session": {
						"source": "hook",
						"agent": "claude",
						"kind": "id",
						"value": "sess-1"
					}
				}
			]
		}
	}`)
	if err := json.Unmarshal(data, &payload); err != nil {
		t.Fatal(err)
	}
	items, recognized := herdrAgentItems(payload)
	if !recognized {
		t.Fatal("expected recognized Herdr response")
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}
	target, pane := herdrTarget(items[0])
	if target != "auth-agent" {
		t.Fatalf("target = %q, want auth-agent", target)
	}
	if pane != "w1:p1" {
		t.Fatalf("pane = %q, want w1:p1", pane)
	}
	if got := normalizeStatus(firstString(items[0], "agent_status")); got != "needs_attention" {
		t.Fatalf("status = %q", got)
	}
	ref, agent := agentSessionRef(items[0])
	if ref != "sess-1" || agent != "claude" {
		t.Fatalf("session ref = %q, agent = %q", ref, agent)
	}
}

func TestHerdrAgentItemsRecognizesExplicitEmptyList(t *testing.T) {
	items, recognized := herdrAgentItems(map[string]any{
		"result": map[string]any{"agents": []any{}},
	})
	if !recognized || len(items) != 0 {
		t.Fatalf("explicit empty list not recognized: recognized=%v items=%v", recognized, items)
	}
}

func TestHerdrAgentItemsRejectsUnknownShape(t *testing.T) {
	if items, recognized := herdrAgentItems(map[string]any{}); recognized || items != nil {
		t.Fatalf("unknown shape accepted: recognized=%v items=%v", recognized, items)
	}
	if items, recognized := herdrAgentItems(map[string]any{"id": "cli:agent:list"}); recognized || items != nil {
		t.Fatalf("envelope id accepted as an agent: recognized=%v items=%v", recognized, items)
	}
}

func TestHerdrAgentListUsesDefaultJSONOutput(t *testing.T) {
	args := herdrAgentListArgs()
	if len(args) != 2 || args[0] != "agent" || args[1] != "list" {
		t.Fatalf("unexpected Herdr args: %v", args)
	}
}

func TestHerdrScannerAcceptsCurrentCLIShape(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell fixture is Unix-only")
	}
	binDir := t.TempDir()
	script := `#!/bin/sh
if [ "$#" -ne 2 ] || [ "$1" != "agent" ] || [ "$2" != "list" ]; then
  exit 2
fi
printf '%s\n' '{"result":{"agents":[{"name":"auth-agent","pane_id":"w1:p1","kind":"claude","agent_status":"blocked","foreground_cwd":"/repo"}]}}'
`
	if err := os.WriteFile(filepath.Join(binDir, "herdr"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))

	result := (HerdrScanner{}).Scan(context.Background())
	if result.Err != nil || !result.SnapshotComplete {
		t.Fatalf("scan failed: %+v", result)
	}
	if len(result.Runtimes) != 1 || result.Runtimes[0].Status != "needs_attention" {
		t.Fatalf("unexpected runtimes: %+v", result.Runtimes)
	}
}

func TestResumeCommandForKnownAgents(t *testing.T) {
	tests := map[string]string{
		"claude":  "claude --resume 'abc'",
		"copilot": "copilot --resume='abc'",
		"hermes":  "hermes --resume 'abc'",
	}
	for agent, want := range tests {
		if got := resumeCommand(agent, "abc"); got != want {
			t.Fatalf("resumeCommand(%q) = %q, want %q", agent, got, want)
		}
	}
}

