)

type Scanner interface {
	Name() string
	Scan(context.Context) core.ScanResult
}

func DefaultScanners(cfg config.Config) []Scanner {
	scanners := []Scanner{
		ClaudeScanner{Root: cfg.Sources.ClaudeProjects},
		CopilotScanner{Root: cfg.Sources.CopilotSessionState},
	}
	return append(scanners, LiveScanners()...)
}

func LiveScanners() []Scanner {
	return []Scanner{
		HerdrScanner{},
		TmuxScanner{},
	}
}

package adapters

import (
	"context"
	"errors"
	"os/exec"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type TmuxScanner struct{}

func (s TmuxScanner) Name() string {
	return "tmux"
}

func (s TmuxScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if _, err := exec.LookPath("tmux"); err != nil {
		result.Skipped = true
		result.Message = "tmux not found"
		return result
	}
	format := strings.Join([]string{
		"#{session_name}",
		"#{window_index}",
		"#{pane_index}",
		"#{pane_id}",
		"#{pane_current_path}",
		"#{pane_current_command}",
		"#{pane_title}",
		"#{pane_active}",
	}, "\x1f")
	out, err := exec.CommandContext(ctx, "tmux", "list-panes", "-a", "-F", format).CombinedOutput()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && isNoTmuxServer(string(out)) {
			result.Skipped = true
			result.SnapshotComplete = true
			result.Message = "tmux server not running"
			return result
		}
		if ctx.Err() != nil {
			result.Err = ctx.Err()
			return result
		}
		result.Err = err
		return result
	}
	result.SnapshotComplete = true
	now := time.Now().UTC()
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		parts := strings.Split(line, "\x1f")
		if len(parts) < 8 {
			continue
		}
		sessionName, windowIndex, paneIndex, paneID := parts[0], parts[1], parts[2], parts[3]
		cwd, command, title := parts[4], parts[5], parts[6]
		agent, isAgent := detectAgentCommand(command)
		if !isAgent {
			continue
		}
		nativeID := paneID
		sess := core.NewSession("tmux", nativeID)
		sess.ProjectPath = cwd
		sess.Agent = agent
		sess.Title = "tmux " + sessionName + ":" + windowIndex + "." + paneIndex
		if title != "" && title != command {
			sess.Title += " " + core.Truncate(title, 32)
		}
		sess.Status = inferRuntimeStatus(command)
		sess.LastActivityAt = now
		sess.CreatedAt = now
		sess.AttachCommand = core.TmuxAttachCommand(sessionName)
		result.Sessions = append(result.Sessions, sess)
		rt := core.RuntimeInstance{
			ID:            core.RuntimeID("tmux", nativeID),
			SessionID:     sess.ID,
			Backend:       "tmux",
			NativeID:      nativeID,
			Surface:       sessionName + ":" + windowIndex + "." + paneIndex,
			ProjectPath:   cwd,
			Command:       command,
			Status:        sess.Status,
			AttachCommand: sess.AttachCommand,
			UpdatedAt:     now,
		}
		result.Runtimes = append(result.Runtimes, rt)
	}
	return result
}

func detectAgentCommand(command string) (string, bool) {
	command = strings.ToLower(strings.TrimSpace(command))
	agents := map[string]string{
		"aider":        "aider",
		"amp":          "amp",
		"claude":       "claude",
		"cline":        "cline",
		"codex":        "codex",
		"copilot":      "copilot",
		"cursor-agent": "cursor-agent",
		"devin":        "devin",
		"droid":        "droid",
		"gemini":       "gemini",
		"grok":         "grok",
		"hermes":       "hermes",
		"kilo":         "kilo",
		"kimi":         "kimi",
		"kiro":         "kiro",
		"mastracode":   "mastracode",
		"omp":          "omp",
		"opencode":     "opencode",
		"pi":           "pi",
		"qodercli":     "qodercli",
	}
	agent, ok := agents[command]
	return agent, ok
}

func isNoTmuxServer(output string) bool {
	output = strings.ToLower(output)
	return strings.Contains(output, "no server running") ||
		strings.Contains(output, "failed to connect to server") ||
		strings.Contains(output, "error connecting to")
}

func inferRuntimeStatus(command string) string {
	switch strings.ToLower(command) {
	case "", "bash", "zsh", "fish", "sh", "tmux":
		return core.StatusIdle
	default:
		return core.StatusUnknown
	}
}

package adapters

import (
	"context"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

func TestDetectAgentCommandRejectsOrdinaryShells(t *testing.T) {
	for _, command := range []string{"", "zsh", "bash", "fish", "node", "python"} {
		if agent, ok := detectAgentCommand(command); ok {
			t.Fatalf("ordinary command %q detected as %q", command, agent)
		}
	}
}

func TestDetectAgentCommandRecognizesKnownAgents(t *testing.T) {
	tests := map[string]string{
		"claude":       "claude",
		"copilot":      "copilot",
		"codex":        "codex",
		"hermes":       "hermes",
		"cursor-agent": "cursor-agent",
	}
	for command, want := range tests {
		got, ok := detectAgentCommand(command)
		if !ok || got != want {
			t.Fatalf("detectAgentCommand(%q) = %q, %v; want %q, true", command, got, ok, want)
		}
	}
}

func TestTmuxScannerIgnoresOrdinaryPanes(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell fixture is Unix-only")
	}
	binDir := t.TempDir()
	script := `#!/bin/sh
printf 'work\0370\0370\037pane-shell\037/repo/shell\037zsh\037shell\0371\n'
printf 'work\0370\0371\037pane-agent\037/repo/agent\037claude\037agent\0370\n'
`
	if err := os.WriteFile(filepath.Join(binDir, "tmux"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))

	result := (TmuxScanner{}).Scan(context.Background())
	if result.Err != nil || !result.SnapshotComplete {
		t.Fatalf("scan failed: %+v", result)
	}
	if len(result.Runtimes) != 1 || result.Runtimes[0].NativeID != "pane-agent" {
		t.Fatalf("unexpected runtimes: %+v", result.Runtimes)
	}
	if len(result.Sessions) != 1 || result.Sessions[0].Agent != "claude" {
		t.Fatalf("unexpected sessions: %+v", result.Sessions)
	}
}

package cli

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/adapters"
	"github.com/jdbencardinop/tesserasessions/internal/buildinfo"
	"github.com/jdbencardinop/tesserasessions/internal/config"
	"github.com/jdbencardinop/tesserasessions/internal/core"
	"github.com/jdbencardinop/tesserasessions/internal/store"
	"github.com/jdbencardinop/tesserasessions/internal/summarize"
	"github.com/spf13/cobra"
)

type appContext struct {
	configPath string
	dbPath     string
}

func mergeSessions(primary, secondary []core.Session) []core.Session {
	seen := make(map[string]bool)
	var out []core.Session
	for _, sess := range primary {
		if seen[sess.ID] {
			continue
		}
		seen[sess.ID] = true
		out = append(out, sess)
	}
	for _, sess := range secondary {
		if seen[sess.ID] {
			continue
		}
		seen[sess.ID] = true
		out = append(out, sess)
	}
	return out
}

func Execute() error {
	app := &appContext{}
	root := &cobra.Command{
		Use:     "tss",
		Short:   "Inventory local coding-agent sessions",
		Long:    "tss inventories local coding-agent sessions and connects them to Herdr or tmux when available.",
		Version: buildinfo.String(),
	}
	root.SetVersionTemplate("tss {{.Version}}\n")
	root.PersistentFlags().StringVar(&app.configPath, "config", "", "config file path")
	root.PersistentFlags().StringVar(&app.dbPath, "db", "", "SQLite database path")
	root.AddCommand(
		app.scanCmd(),
		app.statusCmd(),
		app.listCmd(),
		app.showCmd(),
		app.doctorCmd(),
		app.summarizeCmd(),
		app.searchCmd(),
		app.titleCmd(),
		app.markCmd(),
		app.pinCmd(),
		app.tagCmd(),
		app.attachCmd(),
		app.openCmd(),
		app.sendCmd(),
		app.readCmd(),
		app.runCmd(),
	)
	return root.Execute()
}

func (a *appContext) load() (config.Config, error) {
	cfg, err := config.Load(a.configPath)
	if err != nil {
		return cfg, err
	}
	if a.dbPath != "" {
		cfg.Database = a.dbPath
	}
	return cfg, nil
}

func (a *appContext) openStore(cfg config.Config) (*store.Store, error) {
	if err := config.EnsureDirs(cfg); err != nil {
		return nil, err
	}
	return store.Open(cfg.Database)
}

func (a *appContext) scanCmd() *cobra.Command {
	var source string
	var jsonOutput bool
	cmd := &cobra.Command{
		Use:   "scan",
		Short: "Refresh the local session inventory",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := a.load()
			if err != nil {
				return err
			}
			db, err := a.openStore(cfg)
			if err != nil {
				return err
			}
			defer db.Close() //nolint:errcheck
			ctx := cmd.Context()
			type report struct {
				Source   string `json:"source"`
				Sessions int    `json:"sessions"`
				Runtimes int    `json:"runtimes"`
				Skipped  bool   `json:"skipped"`
				Message  string `json:"message,omitempty"`
				Error    string `json:"error,omitempty"`
			}
			var reports []report
			for _, scanner := range adapters.DefaultScanners(cfg) {
				if source != "" && scanner.Name() != source {
					continue
				}
				res := scanner.Scan(ctx)
				r := report{Source: res.Source, Sessions: len(res.Sessions), Runtimes: len(res.Runtimes), Skipped: res.Skipped, Message: res.Message}
				if res.Err != nil {
					r.Error = res.Err.Error()
					_ = db.UpsertSource(ctx, res.Source, "scanner", sourcePath(cfg, res.Source), r.Error)
					reports = append(reports, r)
					continue
				}
				for _, sess := range res.Sessions {
					if err := db.UpsertSession(ctx, sess); err != nil {
						return err
					}
				}
				if err := persistScanRuntimes(ctx, db, res); err != nil {
					return err
				}
				_ = db.UpsertSource(ctx, res.Source, "scanner", sourcePath(cfg, res.Source), "")
				reports = append(reports, r)
			}
			if jsonOutput {
				return json.NewEncoder(os.Stdout).Encode(reports)
			}
			for _, r := range reports {
				if r.Error != "" {
					fmt.Printf("%s: error: %s\n", r.Source, r.Error)
					continue
				}
				if r.Skipped {
					fmt.Printf("%s: skipped (%s)\n", r.Source, r.Message)
					continue
				}
				fmt.Printf("%s: %d session(s), %d runtime(s)\n", r.Source, r.Sessions, r.Runtimes)
			}
			count, err := db.CountSessions(ctx)
			if err == nil {
				fmt.Printf("Inventory: %d session(s)\n", count)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&source, "source", "", "scan one source (claude, copilot, herdr, tmux)")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "print JSON")
	return cmd
}

func persistScanRuntimes(ctx context.Context, db *store.Store, result core.ScanResult) error {
	if result.Err == nil && result.SnapshotComplete {
		return db.ReplaceRuntimes(ctx, result.Source, result.Runtimes)
	}
	for _, runtime := range result.Runtimes {
		if err := db.UpsertRuntime(ctx, runtime); err != nil {
			return err
		}
	}
	return nil
}

