type statusScannerStub struct{}

func (statusScannerStub) Name() string {
	return "stub"
}

func (statusScannerStub) Scan(context.Context) core.ScanResult {
	return core.ScanResult{
		Source:           "stub",
		SnapshotComplete: true,
		Runtimes: []core.RuntimeInstance{{
			ID:          "stub-1",
			Backend:     "stub",
			NativeID:    "native-1",
			ProjectPath: "/repo",
			Status:      core.StatusWorking,
		}},
	}
}

func TestStatusCommandUsesVersionedLowercaseJSONWithoutDatabase(t *testing.T) {
	dataDir := t.TempDir()
	t.Setenv("TSS_DATA_DIR", dataDir)

	service := statusprovider.NewService([]adapters.Scanner{statusScannerStub{}})
	service.Now = func() time.Time {
		return time.Date(2026, 8, 11, 8, 0, 0, 0, time.UTC)
	}
	service.ResolveGit = func(context.Context, string) (string, string, error) {
		return "", "", nil
	}

	cmd := newStatusCmd(service)
	cmd.SetArgs([]string{"--json"})
	cmd.SetIn(strings.NewReader(`{"schema_version":1,"queries":[{"query_id":"repo","path":"/repo"}]}`))
	var stdout, stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	if err := cmd.Execute(); err != nil {
		t.Fatalf("status failed: %v\n%s", err, stderr.String())
	}

	if strings.Contains(stdout.String(), "SchemaVersion") || !strings.Contains(stdout.String(), `"schema_version":1`) {
		t.Fatalf("wire JSON is not explicit lowercase schema: %s", stdout.String())
	}
	var response statusprovider.Response
	if err := json.Unmarshal(stdout.Bytes(), &response); err != nil {
		t.Fatal(err)
	}
	if response.Results[0].RuntimePresence != statusprovider.RuntimePresent ||
		response.Results[0].AgentState != statusprovider.AgentWorking {
		t.Fatalf("unexpected response: %+v", response.Results[0])
	}

	entries, err := os.ReadDir(dataDir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 0 {
		t.Fatalf("status command created inventory state: %+v", entries)
	}
}

func TestStatusCommandRequiresJSON(t *testing.T) {
	cmd := newStatusCmd(statusprovider.NewService(nil))
	cmd.SetArgs(nil)
	if err := cmd.Execute(); err == nil || !strings.Contains(err.Error(), "requires --json") {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestDecodeStatusRequestRejectsUnknownAndTrailingData(t *testing.T) {
	_, err := decodeStatusRequest(strings.NewReader(`{"schema_version":1,"queries":[],"extra":true}`))
	if err == nil {
		t.Fatal("expected unknown field error")
	}
	_, err = decodeStatusRequest(strings.NewReader(`{"schema_version":1,"queries":[]} {}`))
	if err == nil {
		t.Fatal("expected trailing value error")
	}
}

package core

import (
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	StatusNeedsAttention = "needs_attention"
	StatusWorking        = "working"
	StatusIdle           = "idle"
	StatusDone           = "done"
	StatusStale          = "stale"
	StatusUnknown        = "unknown"
)

type Session struct {
	ID             string
	Source         string
	NativeID       string
	ProjectPath    string
	Agent          string
	Title          string
	TitleSource    string
	GoalSummary    string
	Status         string
	Pinned         bool
	Tags           string
	LastActivityAt time.Time
	CreatedAt      time.Time
	UpdatedAt      time.Time
	ResumeCommand  string
	AttachCommand  string
	RawPath        string
}

type RuntimeInstance struct {
	ID            string
	SessionID     string
	Backend       string
	NativeID      string
	Surface       string
	ProjectPath   string
	Command       string
	Status        string
	AttachCommand string
	UpdatedAt     time.Time
}

type ScanResult struct {
	Source           string
	Sessions         []Session
	Runtimes         []RuntimeInstance
	Skipped          bool
	SnapshotComplete bool
	Message          string
	Err              error
}

func CanonicalID(source, nativeID string) string {
	sum := sha1.Sum([]byte(source + "\x00" + nativeID))
	return source + "-" + hex.EncodeToString(sum[:])[:12]
}

func RuntimeID(backend, nativeID string) string {
	sum := sha1.Sum([]byte(backend + "\x00" + nativeID))
	return backend + "-" + hex.EncodeToString(sum[:])[:12]
}

func ProjectID(path string) string {
	if path == "" {
		return ""
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}
	sum := sha1.Sum([]byte(abs))
	return "project-" + hex.EncodeToString(sum[:])[:12]
}

func ProjectName(path string) string {
	if path == "" {
		return "unknown project"
	}
	clean := filepath.Clean(path)
	base := filepath.Base(clean)
	if base == "." || base == string(filepath.Separator) || base == "" {
		return clean
	}
	return base
}

func DecodeClaudeProjectDir(name string) string {
	if strings.HasPrefix(name, "-") {
		decoded := strings.ReplaceAll(name, "-", string(filepath.Separator))
		if decoded != "" {
			return decoded
		}
	}
	return name
}

func ShellQuote(s string) string {
	if s == "" {
		return "''"
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

func SanitizeName(s string) string {
	s = strings.TrimSpace(strings.ToLower(s))
	re := regexp.MustCompile(`[^a-z0-9_.-]+`)
	s = re.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if s == "" {
		return "session"
	}
	if len(s) > 48 {
		return strings.Trim(s[:48], "-")
	}
	return s
}

func Truncate(s string, max int) string {
	s = strings.TrimSpace(strings.Join(strings.Fields(s), " "))
	if max <= 0 || len(s) <= max {
		return s
	}
	if max <= 3 {
		return s[:max]
	}
	return strings.TrimSpace(s[:max-3]) + "..."
}

func ExistingDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

func ExistingFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

func NonZeroTime(t time.Time, fallback time.Time) time.Time {
	if t.IsZero() {
		return fallback
	}
	return t
}

func FormatTime(t time.Time) string {
	if t.IsZero() {
		return "-"
	}
	return t.Local().Format("2006-01-02 15:04")
}

func NewSession(source, nativeID string) Session {
	now := time.Now().UTC()
	return Session{
		ID:        CanonicalID(source, nativeID),
		Source:    source,
		NativeID:  nativeID,
		Status:    StatusUnknown,
		CreatedAt: now,
		UpdatedAt: now,
	}
}

func TmuxAttachCommand(session string) string {
	return fmt.Sprintf("tmux attach -t %s", ShellQuote(session))
}

package statusprovider

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func TestResolveGitUsesCommonRepositoryRootForLinkedWorktree(t *testing.T) {
	repo := filepath.Join(t.TempDir(), "repo")
	worktree := filepath.Join(t.TempDir(), "worktree")
	runGitTestCommand(t, "", "init", repo)
	runGitTestCommand(t, repo, "config", "user.name", "Test User")
	runGitTestCommand(t, repo, "config", "user.email", "test@example.com")
	if err := os.WriteFile(filepath.Join(repo, "README.md"), []byte("test\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runGitTestCommand(t, repo, "add", "README.md")
	runGitTestCommand(t, repo, "commit", "-m", "initial")
	runGitTestCommand(t, repo, "branch", "-M", "main")
	runGitTestCommand(t, repo, "worktree", "add", "-b", "feature/status", worktree)

	root, branch, err := resolveGit(context.Background(), worktree)
	if err != nil {
		t.Fatal(err)
	}
	wantRoot, err := filepath.EvalSymlinks(repo)
	if err != nil {
		t.Fatal(err)
	}
	gotRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		t.Fatal(err)
	}
	if gotRoot != wantRoot {
		t.Fatalf("repo root = %q, want common root %q", gotRoot, wantRoot)
	}
	if branch != "feature/status" {
		t.Fatalf("branch = %q, want feature/status", branch)
	}
}

func runGitTestCommand(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	if dir != "" {
		cmd.Dir = dir
	}
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
	}
}

package statusprovider

import (
	"fmt"
	"path/filepath"
	stdruntime "runtime"
	"strings"
)

const (
	matchQualityDescendant = 1
	matchQualityExact      = 2
	matchQualityRepoBranch = 3
)

type preparedQuery struct {
	index       int
	query       Query
	path        string
	pathKey     string
	repoRoot    string
	repoRootKey string
	errors      []QueryError
}

type preparedObservation struct {
	RuntimeObservation
	pathKey     string
	repoRootKey string
}

type matchCandidate struct {
	queryIndex  int
	matchType   string
	matchedPath string
	rank        int
}

func matchQueries(queries []Query, providers []ProviderStatus, observations []RuntimeObservation) []Result {
	prepared := prepareQueries(queries)
	results := make([]Result, len(queries))
	for index, query := range prepared {
		results[index] = Result{
			QueryID:         query.query.QueryID,
			Metadata:        query.query.Metadata,
			RuntimePresence: RuntimeUnknown,
			AgentState:      AgentUnknown,
			Runtimes:        []RuntimeObservation{},
			Errors:          append([]QueryError{}, query.errors...),
		}
	}

	preparedObservations := prepareObservations(observations)
	bestMatchRank := make([]int, len(results))
	for _, observation := range preparedObservations {
		candidates := candidatesForObservation(prepared, observation)
		if len(candidates) == 0 {
			continue
		}
		best := candidates[0].rank
		var winners []matchCandidate
		for _, candidate := range candidates {
			if candidate.rank > best {
				best = candidate.rank
				winners = winners[:0]
			}
			if candidate.rank == best {
				winners = append(winners, candidate)
			}
		}
		if len(winners) != 1 {
			for _, winner := range winners {
				appendQueryError(&results[winner.queryIndex], QueryError{
					Code:    "ambiguous_match",
					Message: fmt.Sprintf("runtime %s matches multiple queries with equal specificity", observation.ObservationID),
				})
			}
			continue
		}

		winner := winners[0]
		result := &results[winner.queryIndex]
		result.Runtimes = append(result.Runtimes, observation.RuntimeObservation)
		if winner.rank > bestMatchRank[winner.queryIndex] {
			result.Match = &MatchEvidence{Type: winner.matchType, MatchedPath: winner.matchedPath}
			bestMatchRank[winner.queryIndex] = winner.rank
		}
	}

	allProvidersAvailable := len(providers) > 0
	var unavailable []string
	for _, provider := range providers {
		if !provider.Available {
			allProvidersAvailable = false
			unavailable = append(unavailable, provider.Name)
		}
	}

	for index := range results {
		result := &results[index]
		if len(result.Runtimes) > 0 {
			result.RuntimePresence = aggregatePresence(result.Runtimes)
			result.AgentState = aggregateAgentState(result.Runtimes)
			continue
		}
		if len(result.Errors) > 0 {
			continue
		}
		if allProvidersAvailable {
			result.RuntimePresence = RuntimeAbsent
			continue
		}
		if len(unavailable) > 0 {
			appendQueryError(result, QueryError{
				Code:    "coverage_incomplete",
				Message: "unavailable providers: " + strings.Join(unavailable, ", "),
			})
		}
	}
	return results
}

func prepareQueries(queries []Query) []preparedQuery {
	prepared := make([]preparedQuery, len(queries))
	for index, query := range queries {
		item := preparedQuery{index: index, query: query}
		var pathErr, repoErr error
		item.path, item.pathKey, pathErr = canonicalPathParts(query.Path)
		item.repoRoot, item.repoRootKey, repoErr = canonicalPathParts(query.RepoRoot)

		if query.Path != "" && pathErr != nil {
			item.errors = append(item.errors, QueryError{Code: "invalid_path", Message: pathErr.Error()})
		}
		if query.RepoRoot != "" && repoErr != nil {
			item.errors = append(item.errors, QueryError{Code: "invalid_repo_root", Message: repoErr.Error()})
		}
		if query.Path == "" && (query.RepoRoot == "" || strings.TrimSpace(query.GitBranch) == "") {
			item.errors = append(item.errors, QueryError{
				Code:    "insufficient_match_evidence",
				Message: "path or repo_root plus git_branch is required",
			})
		}
		prepared[index] = item
	}
	return prepared
}

func prepareObservations(observations []RuntimeObservation) []preparedObservation {
	prepared := make([]preparedObservation, 0, len(observations))
	for _, observation := range observations {
		_, pathKey, _ := canonicalPathParts(observation.Path)
		_, repoKey, _ := canonicalPathParts(observation.RepoRoot)
		prepared = append(prepared, preparedObservation{
			RuntimeObservation: observation,
			pathKey:            pathKey,
			repoRootKey:        repoKey,
		})
	}
	return prepared
}

func candidatesForObservation(queries []preparedQuery, observation preparedObservation) []matchCandidate {
	var candidates []matchCandidate
	for _, query := range queries {
		if len(query.errors) > 0 {
			continue
		}
		queryBranch := strings.TrimSpace(query.query.GitBranch)
		repoConflict := query.repoRootKey != "" &&
			observation.repoRootKey != "" &&
			observation.repoRootKey != query.repoRootKey
		branchConflict := queryBranch != "" &&
			observation.GitBranch != "" &&
			observation.GitBranch != queryBranch
		if repoConflict || branchConflict {
			continue
		}
		pathCompatible := query.pathKey == "" ||
			observation.pathKey == query.pathKey ||
			pathWithin(observation.pathKey, query.pathKey)
		if query.repoRootKey != "" &&
			queryBranch != "" &&
			observation.repoRootKey == query.repoRootKey &&
			observation.GitBranch == queryBranch &&
			pathCompatible {
			candidates = append(candidates, matchCandidate{
				queryIndex:  query.index,
				matchType:   "repo_branch",
				matchedPath: observation.Path,
				rank:        matchRank(query.pathKey, matchQualityRepoBranch),
			})
			continue
		}
		if query.pathKey == "" || observation.pathKey == "" {
			continue
		}
		if observation.pathKey == query.pathKey {
			candidates = append(candidates, matchCandidate{
				queryIndex:  query.index,
				matchType:   "exact_path",
				matchedPath: observation.Path,
				rank:        matchRank(query.pathKey, matchQualityExact),
			})
			continue
		}
		if pathWithin(observation.pathKey, query.pathKey) {
			candidates = append(candidates, matchCandidate{
				queryIndex:  query.index,
				matchType:   "descendant_path",
				matchedPath: observation.Path,
				rank:        matchRank(query.pathKey, matchQualityDescendant),
			})
		}
	}
	return candidates
}

func canonicalPath(path string) (string, error) {
	display, _, err := canonicalPathParts(path)
	return display, err
}

func canonicalPathParts(path string) (string, string, error) {
	if strings.TrimSpace(path) == "" {
		return "", "", nil
	}
	if !filepath.IsAbs(path) {
		return "", "", fmt.Errorf("path must be absolute: %s", path)
	}
	display := filepath.Clean(path)
	if resolved, err := filepath.EvalSymlinks(display); err == nil {
		display = filepath.Clean(resolved)
	}
	key := display
	if stdruntime.GOOS == "darwin" || stdruntime.GOOS == "windows" {
		key = strings.ToLower(key)
	}
	return display, key, nil
}

func pathWithin(child, parent string) bool {
	relative, err := filepath.Rel(parent, child)
	if err != nil || relative == "." || filepath.IsAbs(relative) {
		return false
	}
	return relative != ".." && !strings.HasPrefix(relative, ".."+string(filepath.Separator))
}

func pathSpecificity(path string) int {
	return len(path)
}

func matchRank(path string, quality int) int {
	return pathSpecificity(path)*10 + quality
}

func aggregatePresence(observations []RuntimeObservation) RuntimePresence {
	best := RuntimeUnknown
	for _, observation := range observations {
		switch observation.RuntimePresence {
		case RuntimePresent:
			return RuntimePresent
		case RuntimeStale:
			best = RuntimeStale
		}
	}
	return best
}

func aggregateAgentState(observations []RuntimeObservation) AgentState {
	best := AgentUnknown
	bestRank := 0
	for _, observation := range observations {
		rank := agentStateRank(observation.AgentState)
		if rank > bestRank {
			best = observation.AgentState
			bestRank = rank
		}
	}
	return best
}

func agentStateRank(state AgentState) int {
	switch state {
	case AgentBlocked:
		return 5
	case AgentWorking:
		return 4
	case AgentReady:
		return 3
	case AgentDone:
		return 2
	default:
		return 1
	}
}

func appendQueryError(result *Result, queryError QueryError) {
	for _, existing := range result.Errors {
		if existing.Code == queryError.Code && existing.Message == queryError.Message {
			return
		}
	}
	result.Errors = append(result.Errors, queryError)
}

package statusprovider

import (
	"context"
	"fmt"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/adapters"
	"github.com/jdbencardinop/tesserasessions/internal/core"
)

const (
	defaultProbeTimeout = 2 * time.Second
	defaultFreshFor     = 10 * time.Second
)

type GitResolver func(context.Context, string) (repoRoot, branch string, err error)

type Service struct {
	Scanners   []adapters.Scanner
	Timeout    time.Duration
	FreshFor   time.Duration
	Now        func() time.Time
	ResolveGit GitResolver
}

func NewService(scanners []adapters.Scanner) *Service {
	return &Service{
		Scanners:   scanners,
		Timeout:    defaultProbeTimeout,
		FreshFor:   defaultFreshFor,
		Now:        time.Now,
		ResolveGit: resolveGit,
	}
}

func (s *Service) Query(ctx context.Context, request Request) (Response, error) {
	if err := validateEnvelope(request); err != nil {
		return Response{}, err
	}
	s.applyDefaults()

	probes := s.probe(ctx)
	observedAt := s.Now().UTC()
	providers := make([]ProviderStatus, 0, len(probes))
	var observations []RuntimeObservation
	for _, probe := range probes {
		providers = append(providers, probe.provider)
		observations = append(observations, probe.observations...)
	}
	freshUntil := observedAt.Add(s.FreshFor)
	for _, provider := range providers {
		if provider.FreshUntil.Before(freshUntil) {
			freshUntil = provider.FreshUntil
		}
	}
	for _, observation := range observations {
		if observation.ExpiresAt.Before(freshUntil) {
			freshUntil = observation.ExpiresAt
		}
	}

	return Response{
		SchemaVersion: SchemaVersion,
		ObservedAt:    observedAt,
		FreshUntil:    freshUntil,
		Providers:     providers,
		Results:       matchQueries(request.Queries, providers, observations),
	}, nil
}

func (s *Service) applyDefaults() {
	if s.Timeout <= 0 {
		s.Timeout = defaultProbeTimeout
	}
	if s.FreshFor <= 0 {
		s.FreshFor = defaultFreshFor
	}
	if s.Now == nil {
		s.Now = time.Now
	}
	if s.ResolveGit == nil {
		s.ResolveGit = resolveGit
	}
}

type probeOutput struct {
	index        int
	provider     ProviderStatus
	observations []RuntimeObservation
}

func (s *Service) probe(ctx context.Context) []probeOutput {
	outputs := make(chan probeOutput, len(s.Scanners))
	var wg sync.WaitGroup

	for index, scanner := range s.Scanners {
		wg.Add(1)
		go func(index int, scanner adapters.Scanner) {
			defer wg.Done()
			outputs <- s.probeOne(ctx, index, scanner)
		}(index, scanner)
	}

	wg.Wait()
	close(outputs)

	result := make([]probeOutput, 0, len(s.Scanners))
	for output := range outputs {
		result = append(result, output)
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].index < result[j].index
	})
	return result
}

func (s *Service) probeOne(parent context.Context, index int, scanner adapters.Scanner) probeOutput {
	ctx, cancel := context.WithTimeout(parent, s.Timeout)
	defer cancel()

	scan := scanner.Scan(ctx)
	observedAt := s.Now().UTC()
	provider := ProviderStatus{
		Name:       scanner.Name(),
		Available:  scan.Err == nil && (!scan.Skipped || scan.SnapshotComplete),
		ObservedAt: observedAt,
		FreshUntil: observedAt.Add(s.FreshFor),
	}
	if scan.Err != nil {
		provider.Error = scan.Err.Error()
	} else if scan.Skipped && !scan.SnapshotComplete {
		provider.Error = scan.Message
	}

	observations := make([]RuntimeObservation, 0, len(scan.Runtimes))
	for _, runtime := range scan.Runtimes {
		observation, err := s.runtimeObservation(ctx, runtime, observedAt)
		observations = append(observations, observation)
		if err != nil {
			provider.Available = false
			provider.Error = "runtime metadata enrichment failed: " + err.Error()
			break
		}
	}
	return probeOutput{index: index, provider: provider, observations: observations}
}

func (s *Service) runtimeObservation(ctx context.Context, runtime core.RuntimeInstance, observedAt time.Time) (RuntimeObservation, error) {
	path, _ := canonicalPath(runtime.ProjectPath)
	repoRoot, branch := "", ""
	var enrichmentErr error
	if path != "" {
		repoRoot, branch, enrichmentErr = s.ResolveGit(ctx, path)
		repoRoot, _ = canonicalPath(repoRoot)
	}

	presence := RuntimePresent
	if runtime.Status == core.StatusStale {
		presence = RuntimeStale
	}

	observationID := runtime.ID
	if observationID == "" {
		observationID = runtime.Backend + ":" + runtime.NativeID
	}
	return RuntimeObservation{
		ObservationID:   observationID,
		Backend:         runtime.Backend,
		NativeID:        runtime.NativeID,
		Path:            path,
		RepoRoot:        repoRoot,
		GitBranch:       branch,
		RuntimePresence: presence,
		AgentState:      agentState(runtime.Status),
		ObservedAt:      observedAt,
		ExpiresAt:       observedAt.Add(s.FreshFor),
	}, enrichmentErr
}

func agentState(status string) AgentState {
	switch status {
	case core.StatusNeedsAttention:
		return AgentBlocked
	case core.StatusWorking:
		return AgentWorking
	case core.StatusIdle:
		return AgentReady
	case core.StatusDone:
		return AgentDone
	default:
		return AgentUnknown
	}
}

func resolveGit(ctx context.Context, path string) (string, string, error) {
	commonDir, err := gitOutput(ctx, path, "rev-parse", "--path-format=absolute", "--git-common-dir")
	if err != nil {
		if ctx.Err() != nil {
			return "", "", ctx.Err()
		}
		return "", "", nil
	}
	root := filepath.Dir(commonDir)
	branch, err := gitOutput(ctx, path, "symbolic-ref", "--quiet", "--short", "HEAD")
	if err != nil && ctx.Err() != nil {
		return root, "", ctx.Err()
	}
	return root, branch, nil
}

func gitOutput(ctx context.Context, path string, args ...string) (string, error) {
	commandArgs := append([]string{"-C", path}, args...)
	out, err := exec.CommandContext(ctx, "git", commandArgs...).Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

func validateEnvelope(request Request) error {
	if request.SchemaVersion != SchemaVersion {
		return fmt.Errorf("unsupported schema_version %d (expected %d)", request.SchemaVersion, SchemaVersion)
	}
	seen := make(map[string]struct{}, len(request.Queries))
	for index, query := range request.Queries {
		id := strings.TrimSpace(query.QueryID)
		if id == "" {
			return fmt.Errorf("queries[%d].query_id is required", index)
		}
		if _, exists := seen[id]; exists {
			return fmt.Errorf("duplicate query_id %q", id)
		}
		seen[id] = struct{}{}
	}
	return nil
}

package statusprovider

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/adapters"
	"github.com/jdbencardinop/tesserasessions/internal/core"
)

var fixedTime = time.Date(2026, 8, 11, 8, 0, 0, 0, time.UTC)

type fakeScanner struct {
	name string
	scan func(context.Context) core.ScanResult
}

func (f fakeScanner) Name() string {
	return f.name
}

func (f fakeScanner) Scan(ctx context.Context) core.ScanResult {
	return f.scan(ctx)
}

func completeScanner(name string, runtimes ...core.RuntimeInstance) adapters.Scanner {
	return fakeScanner{
		name: name,
		scan: func(context.Context) core.ScanResult {
			return core.ScanResult{
				Source:           name,
				Runtimes:         runtimes,
				SnapshotComplete: true,
			}
		},
	}
}

func testService(scanners ...adapters.Scanner) *Service {
	service := NewService(scanners)
	service.Now = func() time.Time { return fixedTime }
	service.ResolveGit = func(context.Context, string) (string, string, error) {
		return "", "", nil
	}
	return service
}

func TestServiceUsesBranchHintForSharedCheckoutPath(t *testing.T) {
	service := testService(completeScanner("herdr", core.RuntimeInstance{
		ID:          "herdr-1",
		Backend:     "herdr",
		NativeID:    "w1:p1",
		ProjectPath: "/repo",
		Status:      core.StatusNeedsAttention,
	}))
	service.ResolveGit = func(context.Context, string) (string, string, error) {
		return "/repo", "feature/a", nil
	}

	metadata := json.RawMessage(`{"workspace_id":"ws-1"}`)
	response, err := service.Query(context.Background(), Request{
		SchemaVersion: SchemaVersion,
		Queries: []Query{
			{QueryID: "a", Path: "/repo", RepoRoot: "/repo", GitBranch: "feature/a", Metadata: metadata},
			{QueryID: "b", Path: "/repo", RepoRoot: "/repo", GitBranch: "feature/b"},
		},
	})
	if err != nil {
		t.Fatal(err)
	}

	first := response.Results[0]
	if first.RuntimePresence != RuntimePresent || first.AgentState != AgentBlocked {
		t.Fatalf("unexpected first aggregate: %+v", first)
	}
	if first.Match == nil || first.Match.Type != "repo_branch" {
		t.Fatalf("expected repo_branch match, got %+v", first.Match)
	}
	if len(first.Runtimes) != 1 {
		t.Fatalf("expected one raw runtime, got %d", len(first.Runtimes))
	}
	if string(first.Metadata) != string(metadata) {
		t.Fatalf("metadata was not echoed: %s", first.Metadata)
	}

	second := response.Results[1]
	if second.RuntimePresence != RuntimeAbsent || len(second.Runtimes) != 0 {
		t.Fatalf("branch b should be absent, got %+v", second)
	}
}

func TestBranchHintDoesNotOverrideSiblingPathContainment(t *testing.T) {
	service := testService(completeScanner(
		"herdr",
		core.RuntimeInstance{
			ID:          "frontend-runtime",
			Backend:     "herdr",
			NativeID:    "frontend",
			ProjectPath: "/repo/frontend",
			Status:      core.StatusWorking,
		},
		core.RuntimeInstance{
			ID:          "backend-runtime",
			Backend:     "herdr",
			NativeID:    "backend",
			ProjectPath: "/repo/backend",
			Status:      core.StatusIdle,
		},
	))
	service.ResolveGit = func(context.Context, string) (string, string, error) {
		return "/repo", "main", nil
	}

	response, err := service.Query(context.Background(), Request{
		SchemaVersion: SchemaVersion,
		Queries: []Query{
			{QueryID: "frontend", Path: "/repo/frontend", RepoRoot: "/repo", GitBranch: "main"},
			{QueryID: "backend", Path: "/repo/backend", RepoRoot: "/repo", GitBranch: "main"},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	if got := response.Results[0].Runtimes; len(got) != 1 || got[0].NativeID != "frontend" {
		t.Fatalf("frontend received wrong runtimes: %+v", got)
	}
	if got := response.Results[1].Runtimes; len(got) != 1 || got[0].NativeID != "backend" {
		t.Fatalf("backend received wrong runtimes: %+v", got)
	}
}

func TestKnownBranchConflictDoesNotFallbackToPath(t *testing.T) {
